class Editor
  attr_reader :history

  def initialize
    @text, @caret, @history = +'', 0, []
  end

  def save = history.push(Marshal.load(Marshal.dump(self), freeze: true))
  def undo = history.empty? ? self : marshal_load(history.pop.marshal_dump)
  def marshal_dump = [@text, @caret]        # state the snapshot captures
  def marshal_load(state) = (@text, @caret = state)
end

