State = Struct.new(:text, :caret)

class Editor
  def initialize
    @state = State.new(+'', 0).freeze
    @history = []                        # caretaker
  end
  def save = @history.push(@state)       # frozen value: safe to share
  def undo = (@state = @history.pop || @state)
  def write(text) = @state = State.new(text.freeze, @state.caret).freeze
end
